// Pre-records every phrase the game can say and writes voice-ru.js.
//
//   node tools/build-voice.mjs [voice] [ratePercent]
//
// Needs RHVoice with Russian voices and ffmpeg:
//   sudo apt-get install rhvoice rhvoice-russian ffmpeg
//
// The phrase list is not kept here. It is generated by the game's own code: the block
// between VOICE-DATA-BEGIN and VOICE-DATA-END in index.html is evaluated and allClips()
// returns every sentence, with "+" in front of each stressed vowel. That keeps the
// recordings and the game in step: add a word in index.html, re-run this script.
import { readFileSync, writeFileSync, mkdtempSync, rmSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const voice = process.argv[2] || 'arina';
const rate = process.argv[3] || '90';

const html = readFileSync(join(root, 'index.html'), 'utf8');
const block = html.match(/\/\* VOICE-DATA-BEGIN \*\/([\s\S]*?)\/\* VOICE-DATA-END \*\//);
if (!block) throw new Error('VOICE-DATA markers not found in index.html');
const { allClips, plain } = new Function(block[1] + '\nreturn { allClips, plain };')();

// "+а" (stress mark before the vowel) becomes "а" followed by a combining acute accent, which RHVoice obeys.
const forSynth = s => s.replace(/\+(.)/g, '$1́');

const clips = allClips();
const dir = mkdtempSync(join(tmpdir(), 'voice-'));
const pack = {};
let bytes = 0, seconds = 0;
try {
  clips.forEach((text, i) => {
    const wav = join(dir, 'c.wav'), mp3 = join(dir, 'c.mp3');
    execFileSync('RHVoice-test', ['-p', voice, '-r', rate, '-o', wav], { input: forSynth(text) + '\n', stdio: ['pipe', 'ignore', 'ignore'] });
    // trim silence at both ends, keep a short tail so clips do not sound clipped when chained
    execFileSync('ffmpeg', ['-v', 'error', '-y', '-i', wav,
      '-af', 'silenceremove=start_periods=1:start_threshold=-45dB,areverse,silenceremove=start_periods=1:start_threshold=-45dB,areverse,apad=pad_dur=0.08',
      '-ac', '1', '-ar', '24000', '-c:a', 'libmp3lame', '-b:a', '32k', mp3]);
    const buf = readFileSync(mp3);
    const dur = Number(execFileSync('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', mp3]).toString());
    if (!(dur > 0.15)) throw new Error(`clip came out empty: "${text}"`);
    pack[plain(text)] = buf.toString('base64');
    bytes += buf.length; seconds += dur;
    if ((i + 1) % 100 === 0) console.log(`${i + 1}/${clips.length}`);
  });
} finally {
  rmSync(dir, { recursive: true, force: true });
}

const out = '/* Generated by tools/build-voice.mjs. Voice: RHVoice "' + voice + '", rate ' + rate + '%. Do not edit by hand. */\n'
  + 'window.VOICE_PACK=' + JSON.stringify(pack) + ';\n';
writeFileSync(join(root, 'voice-ru.js'), out);
console.log(`clips: ${clips.length}, audio: ${(seconds / 60).toFixed(1)} min, mp3: ${(bytes / 1024).toFixed(0)} KB, voice-ru.js: ${(out.length / 1024).toFixed(0)} KB`);
